inflate-browser.mjs.text:
// FlateDecode via the browser's native DecompressionStream API -- no
// dependency to install, and it never leaves the tab: the bytes go straight
// from the File the visitor chose into this stream and back, with nothing
// sent anywhere. Supported in current Chrome, Edge, Firefox, and Safari
// 16.4+. Returns null (never throws) on an unsupported browser or a stream
// that fails to inflate, which the engine treats as "could not be checked".
export async function inflate(bytes) {
  if (typeof DecompressionStream === 'undefined') return null;
  try {
    const ds = new DecompressionStream('deflate');
    const stream = new Blob([bytes]).stream().pipeThrough(ds);
    const buf = await new Response(stream).arrayBuffer();
    return new Uint8Array(buf);
  } catch {
    return null;
  }
}

pdf-fixtures.mjs.text:
// Builds small PDFs for the tests: a statement laid out as positioned text,
// in three encodings real banks use. Test-only; the page never imports it.
import zlib from 'node:zlib';

const esc = (s) => s.replace(/[\\()]/g, (c) => `\\${c}`);

export function layout(text, { colWidth = 5.4, lineHeight = 14, top = 780 } = {}) {
  const out = [];
  text.split('\n').forEach((raw, i) => {
    const re = /\S+(?: \S+)*/g;
    let m;
    while ((m = re.exec(raw))) out.push({ text: m[0], x: 36 + m.index * colWidth, y: top - i * lineHeight });
  });
  return out;
}

function hex2(s) { return [...s].map((c) => c.charCodeAt(0).toString(16).padStart(4, '0')).join(''); }

/** mode: 'plain' (Helvetica, literal strings), 'tounicode' (Type0 Identity-H + ToUnicode CMap, hex glyph ids),
 *  'objstm' (plain fonts, but page/font objects inside a compressed object stream). */
export function buildStatementPdf(text, { mode = 'plain', compress = true, encrypt = false, pages = 1 } = {}) {
  const items = layout(text);
  const per = Math.ceil(items.length / pages);
  const objs = [];
  const add = (body) => { objs.push(body); return objs.length; };
  const streamObj = (dict, data) => {
    const raw = Buffer.from(data, 'latin1');
    const body = compress ? zlib.deflateSync(raw) : raw;
    const d = `<< ${dict} ${compress ? '/Filter /FlateDecode ' : ''}/Length ${body.length} >>`;
    return Buffer.concat([Buffer.from(`${d}\nstream\n`, 'latin1'), body, Buffer.from('\nendstream', 'latin1')]);
  };

  // glyph ids for the ToUnicode variant: code = char code - 31
  const glyphs = new Map();
  const gid = (ch) => { if (!glyphs.has(ch)) glyphs.set(ch, glyphs.size + 1); return glyphs.get(ch); };

  const contents = [];
  for (let p = 0; p < pages; p++) {
    const slice = items.slice(p * per, (p + 1) * per);
    let c = 'BT\n/F1 9 Tf\n';
    for (const it of slice) {
      if (mode === 'tounicode') c += `1 0 0 1 ${it.x.toFixed(2)} ${it.y} Tm <${[...it.text].map((ch) => gid(ch).toString(16).padStart(4, '0')).join('')}> Tj\n`;
      else c += `1 0 0 1 ${it.x.toFixed(2)} ${it.y} Tm (${esc(it.text)}) Tj\n`;
    }
    contents.push(`${c}ET\n`);
  }

  const catalog = add('<< /Type /Catalog /Pages 2 0 R >>');
  const pagesIdx = add(''); // placeholder, filled below
  const fontIdx = add('');  // placeholder
  const pageIdx = [];
  const contentIdx = [];
  for (let p = 0; p < pages; p++) {
    contentIdx.push(add(streamObj('', contents[p])));
    pageIdx.push(add(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 ${fontIdx} 0 R >> >> /Contents ${contentIdx[p]} 0 R >>`));
  }
  objs[pagesIdx - 1] = `<< /Type /Pages /Kids [${pageIdx.map((i) => `${i} 0 R`).join(' ')}] /Count ${pages} >>`;
  if (mode === 'tounicode') {
    const bf = [...glyphs].map(([ch, id]) => `<${id.toString(16).padStart(4, '0')}> <${hex2(ch)}>`);
    const cmap = `/CIDInit /ProcSet findresource begin 12 dict begin begincmap\n1 begincodespacerange\n<0000> <FFFF>\nendcodespacerange\n${bf.length} beginbfchar\n${bf.join('\n')}\nendbfchar\nendcmap end end`;
    const tu = add(streamObj('', cmap));
    const desc = add('<< /Type /Font /Subtype /CIDFontType2 /BaseFont /Sub /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> >>');
    objs[fontIdx - 1] = `<< /Type /Font /Subtype /Type0 /BaseFont /Sub /Encoding /Identity-H /DescendantFonts [${desc} 0 R] /ToUnicode ${tu} 0 R >>`;
  } else {
    objs[fontIdx - 1] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
  }

  const parts = [Buffer.from('%PDF-1.5\n', 'latin1')];
  let useObjStm = false;
  if (mode === 'objstm') {
    useObjStm = true;
  }
  const emit = (n, body) => {
    parts.push(Buffer.from(`${n} 0 obj\n`, 'latin1'));
    parts.push(Buffer.isBuffer(body) ? body : Buffer.from(body, 'latin1'));
    parts.push(Buffer.from('\nendobj\n', 'latin1'));
  };
  const inStm = [];
  objs.forEach((body, i) => {
    const n = i + 1;
    if (useObjStm && typeof body === 'string' && n !== 0) inStm.push([n, body]);
    else emit(n, body);
  });
  let next = objs.length + 1;
  if (inStm.length) {
    let header = '', bodies = '';
    for (const [n, body] of inStm) { header += `${n} ${bodies.length} `; bodies += `${body} `; }
    const data = header + bodies;
    emit(next++, streamObj(`/Type /ObjStm /N ${inStm.length} /First ${header.length}`, data));
  }
  parts.push(Buffer.from(`trailer\n<< /Root ${catalog} 0 R /Size ${next}${encrypt ? ' /Encrypt 99 0 R' : ''} >>\n%%EOF\n`, 'latin1'));
  return new Uint8Array(Buffer.concat(parts));
}

export async function inflate(bytes) {
  try { return new Uint8Array(zlib.inflateSync(Buffer.from(bytes))); } catch { return null; }
}

pdf-parser.mjs.text:
// A small, dependency-free PDF object parser.
//
// This is not a PDF renderer and does not aim to be spec-complete. It is a
// lenient scanner good enough to answer the accessibility-structure
// questions this venture checks: is the document tagged, does it have a
// title and a declared language, do its images have alternate text
// structure elements, do its form-field widgets have accessible names, and
// does a page have a text layer at all. Real-world PDFs vary widely in how
// strictly they follow the spec, so this parser is deliberately forgiving --
// it scans for object patterns directly in the byte stream rather than
// requiring a valid cross-reference table, which is also what lets it read
// a PDF whose xref table is stale or wrong (common after some editors patch
// a file in place).
//
// Byte <-> "binary string" trick: PDF syntax (names, dict punctuation,
// keywords) is pure ASCII even though stream *content* is arbitrary binary.
// Decoding the whole file as Latin-1 gives a 1:1, lossless, reversible
// mapping from byte value to JS UTF-16 code unit, so ordinary string
// methods and regexes can scan the syntax layer directly with no separate
// byte-oriented lexer, and any substring can be converted back to exact
// original bytes with binaryStringToBytes(). pdf.js and pdf-lib use the
// same trick internally.

export function bytesToBinaryString(bytes) {
  let s = '';
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    s += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
  }
  return s;
}

export function binaryStringToBytes(str) {
  const out = new Uint8Array(str.length);
  for (let i = 0; i < str.length; i++) out[i] = str.charCodeAt(i) & 0xff;
  return out;
}

// --- Value model -----------------------------------------------------

export class PName {
  constructor(name) { this.name = name; }
}
export class PString {
  constructor(text) { this.text = text; } // best-effort decoded text, not exact bytes
}
export class PRef {
  constructor(num, gen) { this.num = num; this.gen = gen; }
}
export class PDict {
  constructor() { this.map = new Map(); }
  get(key) { return this.map.get(key); }
  has(key) { return this.map.has(key); }
  set(key, value) { this.map.set(key, value); return this; }
}

function isDict(v) { return v instanceof PDict; }
function isName(v, name) { return v instanceof PName && v.name === name; }

// --- Tiny recursive-descent value parser ------------------------------

const WS = /[\0\t\n\f\r ]/;

function skipWs(str, pos) {
  for (;;) {
    while (pos < str.length && WS.test(str[pos])) pos++;
    if (str[pos] === '%') {
      while (pos < str.length && str[pos] !== '\n' && str[pos] !== '\r') pos++;
      continue;
    }
    return pos;
  }
}

function parseName(str, pos) {
  let i = pos + 1; // skip leading '/'
  let name = '';
  while (i < str.length && !WS.test(str[i]) && !'()<>[]{}/%'.includes(str[i])) {
    if (str[i] === '#' && /[0-9a-fA-F]{2}/.test(str.slice(i + 1, i + 3))) {
      name += String.fromCharCode(parseInt(str.slice(i + 1, i + 3), 16));
      i += 3;
    } else {
      name += str[i];
      i++;
    }
  }
  return [new PName(name), i];
}

function parseLiteralString(str, pos) {
  let i = pos + 1;
  let depth = 1;
  let text = '';
  while (i < str.length && depth > 0) {
    const c = str[i];
    if (c === '\\') {
      const next = str[i + 1];
      const map = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f', '(': '(', ')': ')', '\\': '\\' };
      if (next === '\n') { i += 2; continue; }
      if (next === '\r') { i += str[i + 2] === '\n' ? 3 : 2; continue; }
      if (map[next] !== undefined) { text += map[next]; i += 2; continue; }
      if (/[0-7]/.test(next)) {
        let oct = '';
        let j = i + 1;
        while (j < str.length && oct.length < 3 && /[0-7]/.test(str[j])) { oct += str[j]; j++; }
        text += String.fromCharCode(parseInt(oct, 8) & 0xff);
        i = j;
        continue;
      }
      text += next ?? '';
      i += 2;
      continue;
    }
    if (c === '(') { depth++; text += c; i++; continue; }
    if (c === ')') { depth--; i++; if (depth === 0) break; text += c; continue; }
    text += c;
    i++;
  }
  return [new PString(text), i];
}

function parseHexString(str, pos) {
  let i = pos + 1;
  let hex = '';
  while (i < str.length && str[i] !== '>') { if (/[0-9a-fA-F]/.test(str[i])) hex += str[i]; i++; }
  i++; // skip '>'
  if (hex.length % 2 === 1) hex += '0';
  let text = '';
  for (let k = 0; k < hex.length; k += 2) text += String.fromCharCode(parseInt(hex.slice(k, k + 2), 16));
  return [new PString(text), i];
}

function parseArray(str, pos, parseValueFn) {
  let i = pos + 1;
  const arr = [];
  for (;;) {
    i = skipWs(str, i);
    if (str[i] === ']' || i >= str.length) { i++; break; }
    const [v, next] = parseValueFn(str, i);
    if (next <= i) { i++; continue; } // guard against non-advancing parse
    arr.push(v);
    i = next;
  }
  return [arr, i];
}

function parseDict(str, pos, parseValueFn) {
  let i = pos + 2; // skip '<<'
  const dict = new PDict();
  for (;;) {
    i = skipWs(str, i);
    if (str.startsWith('>>', i) || i >= str.length) { i += 2; break; }
    if (str[i] !== '/') { i++; continue; } // resync on malformed input
    const [key, afterKey] = parseName(str, i);
    i = skipWs(str, afterKey);
    const [value, afterValue] = parseValueFn(str, i);
    dict.set(key.name, value);
    i = afterValue <= i ? i + 1 : afterValue;
  }
  return [dict, i];
}

const NUM_RE = /^[+-]?(\d+\.\d*|\.\d+|\d+)/;

export function parseValue(str, pos) {
  pos = skipWs(str, pos);
  if (pos >= str.length) return [null, pos];
  const c = str[pos];
  if (str.startsWith('<<', pos)) return parseDict(str, pos, parseValue);
  if (c === '[') return parseArray(str, pos, parseValue);
  if (c === '/') return parseName(str, pos);
  if (c === '(') return parseLiteralString(str, pos);
  if (c === '<') return parseHexString(str, pos);
  if (str.startsWith('true', pos)) return [true, pos + 4];
  if (str.startsWith('false', pos)) return [false, pos + 5];
  if (str.startsWith('null', pos)) return [null, pos + 4];
  const m = NUM_RE.exec(str.slice(pos));
  if (m) {
    const numEnd = pos + m[0].length;
    // Look ahead for "<gen> R" to fold into a reference.
    let look = skipWs(str, numEnd);
    const m2 = /^\d+/.exec(str.slice(look));
    if (/^\d+$/.test(m[0]) && m2) {
      const genEnd = look + m2[0].length;
      const afterGen = skipWs(str, genEnd);
      if (str[afterGen] === 'R' && !/[A-Za-z0-9]/.test(str[afterGen + 1] || '')) {
        return [new PRef(parseInt(m[0], 10), parseInt(m2[0], 10)), afterGen + 1];
      }
    }
    return [parseFloat(m[0]), numEnd];
  }
  // Unknown token (keyword like "obj", "endobj", stray operator) -- skip one char.
  return [null, pos + 1];
}

// --- Object scanning ----------------------------------------------------

const OBJ_RE = /(\d+)\s+(\d+)\s+obj\b/g;

/**
 * Scan the whole file for "<n> <g> obj ... endobj" definitions. Lenient:
 * does not require or trust the xref table, so a stale or missing xref
 * cannot hide an object from the checks below (and cannot be exploited to
 * make a check see a stripped-down "clean" copy of a document either).
 *
 * @param {string} str - binary string (see bytesToBinaryString)
 * @returns {Map<number, {dict: PDict|any, streamStart: number, streamEnd: number, filter: PName|PName[]|null}>}
 */
export function scanObjects(str) {
  const objects = new Map();
  OBJ_RE.lastIndex = 0;
  let m;
  while ((m = OBJ_RE.exec(str))) {
    const num = parseInt(m[1], 10);
    const bodyStart = OBJ_RE.lastIndex;
    const endObjIdx = str.indexOf('endobj', bodyStart);
    const bodyEnd = endObjIdx === -1 ? str.length : endObjIdx;
    const streamKw = str.indexOf('stream', bodyStart);
    let dictText = str.slice(bodyStart, bodyEnd);
    let streamStart = -1;
    let streamEnd = -1;
    if (streamKw !== -1 && streamKw < bodyEnd) {
      dictText = str.slice(bodyStart, streamKw);
      let s = streamKw + 'stream'.length;
      if (str[s] === '\r') s++;
      if (str[s] === '\n') s++;
      streamStart = s;
      const endStreamIdx = str.indexOf('endstream', s);
      streamEnd = endStreamIdx === -1 ? bodyEnd : endStreamIdx;
      // Trim a single trailing EOL that precedes "endstream".
      let e = streamEnd;
      if (str[e - 1] === '\n') e--;
      if (str[e - 1] === '\r') e--;
      streamEnd = e;
    }
    const [dict] = parseValue(dictText, 0);
    objects.set(num, { dict, streamStart, streamEnd });
    OBJ_RE.lastIndex = Math.max(bodyEnd, OBJ_RE.lastIndex);
  }
  return objects;
}

/** Finds the last "trailer << ... >>" dict, or the dict of the last object
 * whose own /Type is /XRef (a cross-reference *stream*, which carries the
 * same /Root and /Info keys a classic trailer would -- used by many modern
 * PDF writers instead of a plain trailer keyword). */
export function findTrailer(str, objects) {
  let trailerDict = null;
  const TRAILER_RE = /trailer\b/g;
  let m;
  while ((m = TRAILER_RE.exec(str))) {
    const [dict] = parseValue(str, m.index + m[0].length);
    if (isDict(dict)) trailerDict = dict;
  }
  if (trailerDict) return trailerDict;
  for (const { dict } of objects.values()) {
    if (isDict(dict) && isName(dict.get('Type'), 'XRef')) trailerDict = dict;
  }
  return trailerDict;
}

function resolve(value, objects, depth = 0) {
  if (depth > 32) return null;
  if (value instanceof PRef) {
    const entry = objects.get(value.num);
    if (!entry) return null;
    return resolve(entry.dict, objects, depth + 1);
  }
  return value;
}

/** Filter name(s) declared on a stream dict, as a plain array of strings. */
function filterNames(dict) {
  const f = dict.get('Filter');
  if (!f) return [];
  if (f instanceof PName) return [f.name];
  if (Array.isArray(f)) return f.filter((v) => v instanceof PName).map((v) => v.name);
  return [];
}

/**
 * Returns the raw (still-encoded) bytes of an object's stream, or null.
 */
export function rawStreamBytes(entry, bytes, binaryStr) {
  if (!entry || entry.streamStart < 0) return null;
  return binaryStringToBytes(binaryStr.slice(entry.streamStart, entry.streamEnd));
}

/**
 * Decodes a stream's bytes by applying its declared filter chain, using the
 * supplied async inflate(bytes) -> Uint8Array|null for FlateDecode (the
 * only filter this tool supports: it's what essentially all modern PDF
 * writers use for both content streams and object/xref streams). A stream
 * using any other filter, or one that fails to inflate (garbled data,
 * encryption), decodes to null rather than throwing -- callers treat that
 * as "could not be checked", never as "checked and clean".
 */
export async function decodeStream(entry, binaryStr, inflate) {
  const raw = rawStreamBytes(entry, null, binaryStr);
  if (!raw) return null;
  const filters = filterNames(entry.dict instanceof PDict ? entry.dict : new PDict());
  if (filters.length === 0) return raw;
  let data = raw;
  for (const name of filters) {
    if (name !== 'FlateDecode' && name !== 'Fl') return null; // unsupported filter chain
    if (!data) return null;
    data = await inflate(data);
  }
  return data;
}

/**
 * Expands compressed object streams (/Type /ObjStm) into the main object
 * map, mutating and returning it. Objects already present from a plain
 * scan are left untouched -- a compressed definition should never need to
 * override one this parser already read directly.
 */
export async function expandObjectStreams(objects, binaryStr, inflate) {
  const objStms = [];
  for (const [num, entry] of objects) {
    if (isDict(entry.dict) && isName(entry.dict.get('Type'), 'ObjStm')) objStms.push([num, entry]);
  }
  for (const [, entry] of objStms) {
    const decoded = await decodeStream(entry, binaryStr, inflate);
    if (!decoded) continue;
    const bodyStr = bytesToBinaryString(decoded);
    const n = resolve(entry.dict.get('N'), objects);
    const first = resolve(entry.dict.get('First'), objects);
    if (typeof n !== 'number' || typeof first !== 'number') continue;
    const header = bodyStr.slice(0, first);
    const pairs = header.trim().split(/\s+/).map((s) => parseInt(s, 10));
    for (let i = 0; i < n; i++) {
      const objNum = pairs[i * 2];
      const offset = pairs[i * 2 + 1];
      if (!Number.isFinite(objNum) || !Number.isFinite(offset)) continue;
      if (objects.has(objNum)) continue;
      const [value] = parseValue(bodyStr, first + offset);
      objects.set(objNum, { dict: value, streamStart: -1, streamEnd: -1 });
    }
  }
  return objects;
}

export { isDict, isName, resolve };

pdf-text.mjs.text:
// Text extraction from a PDF that has a text layer, with positions.
//
// Built on the lenient object scanner in pdf-parser.mjs (copied from the
// pdf-accessibility-tag-check venture). It reads each page's content stream,
// follows the text operators (Tf, Td, TD, Tm, T*, Tj, TJ, ', ") and the
// graphics state's cm/q/Q so that every run of text comes out with an x and a
// "row" position, then groups runs into lines. It does not render anything and
// does not do OCR: a scanned statement has no text to read, and says so.
//
// Fonts: a ToUnicode CMap is used when the font has one (this is what makes
// subset TrueType and Identity-H fonts readable). Without one, a simple font
// is read as Latin-1 with any /Differences glyph names applied, and a
// composite font is reported as unreadable instead of guessed at.

import {
  bytesToBinaryString, scanObjects, findTrailer, expandObjectStreams, decodeStream,
  resolve, isDict, isName, PName, PString, PRef, PDict, parseValue,
} from './pdf-parser.mjs';

// --- CMap -------------------------------------------------------------

function hexToUtf16(hex) {
  let s = '';
  for (let i = 0; i + 3 < hex.length + 1; i += 4) {
    const chunk = hex.slice(i, i + 4);
    if (chunk.length < 4) { s += String.fromCharCode(parseInt(chunk.padEnd(4, '0'), 16)); break; }
    s += String.fromCharCode(parseInt(chunk, 16));
  }
  return s;
}

export function parseCMap(text) {
  const map = new Map();
  let codeLen = 0;
  for (const m of text.matchAll(/begincodespacerange([\s\S]*?)endcodespacerange/g)) {
    for (const h of m[1].matchAll(/<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>/g)) codeLen = Math.max(codeLen, h[1].length / 2);
  }
  for (const m of text.matchAll(/beginbfchar([\s\S]*?)endbfchar/g)) {
    for (const h of m[1].matchAll(/<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]*)>/g)) {
      map.set(parseInt(h[1], 16), hexToUtf16(h[2]));
      if (!codeLen) codeLen = h[1].length / 2;
    }
  }
  for (const m of text.matchAll(/beginbfrange([\s\S]*?)endbfrange/g)) {
    const body = m[1];
    const re = /<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>\s*(?:<([0-9a-fA-F]*)>|\[([^\]]*)\])/g;
    let h;
    while ((h = re.exec(body))) {
      const lo = parseInt(h[1], 16), hi = parseInt(h[2], 16);
      if (!codeLen) codeLen = h[1].length / 2;
      if (hi < lo || hi - lo > 0xffff) continue;
      if (h[3] !== undefined) {
        const base = hexToUtf16(h[3]);
        const lastCode = base.length ? base.charCodeAt(base.length - 1) : 0;
        for (let c = lo; c <= hi; c++) map.set(c, base.slice(0, -1) + String.fromCharCode(lastCode + (c - lo)));
      } else {
        const list = [...(h[4] || '').matchAll(/<([0-9a-fA-F]*)>/g)].map((x) => hexToUtf16(x[1]));
        for (let c = lo; c <= hi && c - lo < list.length; c++) map.set(c, list[c - lo]);
      }
    }
  }
  return { map, codeLen: codeLen || 0 };
}

// A small glyph-name table, enough for /Differences arrays on simple fonts.
const GLYPHS = {
  space: ' ', exclam: '!', quotedbl: '"', numbersign: '#', dollar: '$', percent: '%', ampersand: '&', quotesingle: "'",
  parenleft: '(', parenright: ')', asterisk: '*', plus: '+', comma: ',', hyphen: '-', minus: '-', period: '.', slash: '/',
  zero: '0', one: '1', two: '2', three: '3', four: '4', five: '5', six: '6', seven: '7', eight: '8', nine: '9',
  colon: ':', semicolon: ';', less: '<', equal: '=', greater: '>', question: '?', at: '@', bracketleft: '[',
  backslash: '\\', bracketright: ']', underscore: '_', grave: '`', braceleft: '{', bar: '|', braceright: '}',
  asciitilde: '~', endash: '–', emdash: '—', bullet: '•', Euro: '€', sterling: '£', yen: '¥', cent: '¢', quoteright: '’',
  quoteleft: '‘', quotedblleft: '“', quotedblright: '”', nbspace: ' ', nonbreakingspace: ' ',
};
function glyphToChar(name) {
  if (name in GLYPHS) return GLYPHS[name];
  if (/^[A-Za-z]$/.test(name)) return name;
  let m = /^uni([0-9A-Fa-f]{4})$/.exec(name);
  if (m) return String.fromCharCode(parseInt(m[1], 16));
  return null;
}

// --- Fonts --------------------------------------------------------------

async function loadFont(fontRef, objects, binaryStr, inflate) {
  const font = { cmap: null, codeLen: 1, differences: null, unreadable: false };
  const dict = resolve(fontRef, objects);
  if (!isDict(dict)) return font;
  const composite = isName(dict.get('Subtype'), 'Type0');
  if (composite) font.codeLen = 2;
  const tu = dict.get('ToUnicode');
  if (tu instanceof PRef) {
    const entry = objects.get(tu.num);
    const data = entry ? await decodeStream(entry, binaryStr, inflate) : null;
    if (data) {
      const cm = parseCMap(bytesToBinaryString(data));
      if (cm.map.size) { font.cmap = cm.map; if (cm.codeLen) font.codeLen = cm.codeLen; }
    }
  }
  if (!font.cmap) {
    if (composite) font.unreadable = true;
    else {
      const enc = resolve(dict.get('Encoding'), objects);
      if (isDict(enc)) {
        const diffs = resolve(enc.get('Differences'), objects);
        if (Array.isArray(diffs)) {
          font.differences = new Map();
          let code = 0;
          for (const d of diffs) {
            if (typeof d === 'number') code = d;
            else if (d instanceof PName) { const ch = glyphToChar(d.name); if (ch !== null) font.differences.set(code, ch); code++; }
          }
        }
      }
    }
  }
  return font;
}

function decodeString(str, font) {
  if (!font) return str;
  let out = '';
  if (font.cmap) {
    const n = font.codeLen || 1;
    for (let i = 0; i + n <= str.length; i += n) {
      let code = 0;
      for (let k = 0; k < n; k++) code = code * 256 + (str.charCodeAt(i + k) & 0xff);
      const ch = font.cmap.get(code);
      out += ch === undefined ? (n === 1 ? str[i] : '') : ch;
    }
    return out;
  }
  if (font.unreadable) return '';
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i) & 0xff;
    const d = font.differences ? font.differences.get(code) : undefined;
    out += d !== undefined ? d : String.fromCharCode(code);
  }
  return out;
}

// --- Content stream -----------------------------------------------------

// Tokenizer for a content stream: yields operands and operators.
function* tokens(str) {
  let i = 0;
  const n = str.length;
  const WS = /[\0\t\n\f\r ]/;
  while (i < n) {
    const c = str[i];
    if (WS.test(c)) { i++; continue; }
    if (c === '%') { while (i < n && str[i] !== '\n' && str[i] !== '\r') i++; continue; }
    if (c === '(' || c === '<' || c === '[' || c === '/') {
      if (c === '<' && str[i + 1] === '<') { const [v, next] = parseValue(str, i); yield { v }; i = Math.max(next, i + 1); continue; }
      const [v, next] = parseValue(str, i);
      yield { v: c === '(' || c === '<' ? v : v };
      i = Math.max(next, i + 1);
      continue;
    }
    let j = i;
    while (j < n && !WS.test(str[j]) && !'()<>[]{}/%'.includes(str[j])) j++;
    if (j === i) { i++; continue; }
    const word = str.slice(i, j);
    i = j;
    if (/^[+-]?(\d+\.?\d*|\.\d+)$/.test(word)) yield { v: parseFloat(word) };
    else if (word === 'BI') {
      const end = str.indexOf('EI', i);
      i = end === -1 ? n : end + 2;
    } else yield { op: word };
  }
}

function mul(m, n) { // m then n  (row-vector convention used by PDF)
  return [
    m[0] * n[0] + m[1] * n[2], m[0] * n[1] + m[1] * n[3],
    m[2] * n[0] + m[3] * n[2], m[2] * n[1] + m[3] * n[3],
    m[4] * n[0] + m[5] * n[2] + n[4], m[4] * n[1] + m[5] * n[3] + n[5],
  ];
}

export function textRuns(content, fonts) {
  const runs = [];
  let ctm = [1, 0, 0, 1, 0, 0];
  const stack = [];
  let tm = [1, 0, 0, 1, 0, 0], tlm = [1, 0, 0, 1, 0, 0];
  let font = null, fontSize = 10, leading = 0;
  let operands = [];
  const emit = (str) => {
    const text = decodeString(str, font);
    const trm = mul(tm, ctm);
    const size = Math.abs(fontSize * (Math.abs(trm[3]) || 1));
    const adv = size * 0.5 * text.length * Math.abs(tm[0] || 1);
    if (text !== '') runs.push({ text, x: trm[4], y: trm[5], size, flip: ctm[3] < 0 || tm[3] < 0, unreadable: Boolean(font && font.unreadable && text === '') });
    else if (font && font.unreadable && str.length) runs.push({ text: '', x: trm[4], y: trm[5], size, flip: false, unreadable: true });
    tm = mul([1, 0, 0, 1, adv / (Math.abs(ctm[0]) || 1), 0], tm);
  };
  for (const t of tokens(content)) {
    if (!('op' in t)) { operands.push(t.v); if (operands.length > 64) operands.shift(); continue; }
    const op = t.op;
    const num = (k) => (typeof operands[k] === 'number' ? operands[k] : 0);
    switch (op) {
      case 'q': stack.push(ctm.slice()); break;
      case 'Q': if (stack.length) ctm = stack.pop(); break;
      case 'cm': if (operands.length >= 6) ctm = mul(operands.slice(-6).map((x) => (typeof x === 'number' ? x : 0)), ctm); break;
      case 'BT': tm = [1, 0, 0, 1, 0, 0]; tlm = tm.slice(); break;
      case 'Tf': {
        const nameOp = operands.find((x) => x instanceof PName);
        font = nameOp ? (fonts.get(nameOp.name) || null) : null;
        const sz = operands.filter((x) => typeof x === 'number').pop();
        if (typeof sz === 'number') fontSize = sz;
        break;
      }
      case 'TL': leading = num(0); break;
      case 'Td': case 'TD': {
        const tx = num(operands.length - 2), ty = num(operands.length - 1);
        if (op === 'TD') leading = -ty;
        tlm = mul([1, 0, 0, 1, tx, ty], tlm); tm = tlm.slice();
        break;
      }
      case 'Tm': if (operands.length >= 6) { tm = operands.slice(-6).map((x) => (typeof x === 'number' ? x : 0)); tlm = tm.slice(); } break;
      case 'T*': tlm = mul([1, 0, 0, 1, 0, -leading], tlm); tm = tlm.slice(); break;
      case 'Tj': { const s = operands[operands.length - 1]; if (s instanceof PString) emit(s.text); break; }
      case "'": case '"': {
        tlm = mul([1, 0, 0, 1, 0, -leading], tlm); tm = tlm.slice();
        const s = operands[operands.length - 1]; if (s instanceof PString) emit(s.text);
        break;
      }
      case 'TJ': {
        const arr = operands[operands.length - 1];
        if (Array.isArray(arr)) {
          let pending = '';
          const flush = () => { if (pending !== '') { emit(pending); pending = ''; } };
          for (const el of arr) {
            if (el instanceof PString) pending += el.text;
            else if (typeof el === 'number') {
              if (el < -180) { flush(); tm = mul([1, 0, 0, 1, (-el / 1000) * fontSize * (Math.abs(tm[0]) || 1), 0], tm); }
              else if (el !== 0) { /* kerning: small shift, keep in the same run */ }
            }
          }
          flush();
        }
        break;
      }
      default: break;
    }
    operands = [];
  }
  return runs;
}

// Group runs into lines, top to bottom, items left to right.
export function groupLines(runs, page = 1) {
  if (!runs.length) return [];
  const flip = runs.filter((r) => r.flip).length > runs.length / 2;
  const items = runs.map((r) => ({ ...r, key: flip ? r.y : -r.y }));
  items.sort((a, b) => a.key - b.key || a.x - b.x);
  const lines = [];
  for (const it of items) {
    const last = lines[lines.length - 1];
    const tol = Math.max(1.5, (it.size || 10) * 0.35);
    if (last && Math.abs(last.key - it.key) <= tol) last.items.push(it);
    else lines.push({ key: it.key, items: [it], page });
  }
  return lines.map((l) => {
    l.items.sort((a, b) => a.x - b.x);
    return {
      page: l.page,
      items: l.items.map((it) => ({ text: it.text.replace(/ /g, ' '), x: it.x, xEnd: it.x + it.size * 0.5 * it.text.length })),
    };
  });
}

// --- Pages --------------------------------------------------------------

function inherited(dict, key, objects) {
  let d = dict;
  for (let i = 0; i < 24 && isDict(d); i++) {
    if (d.has(key)) return resolve(d.get(key), objects);
    d = resolve(d.get('Parent'), objects);
  }
  return null;
}

function pageList(objects, trailer) {
  const pages = [];
  const seen = new Set();
  const walk = (ref, depth) => {
    if (depth > 24) return;
    const num = ref instanceof PRef ? ref.num : null;
    if (num !== null && seen.has(num)) return;
    if (num !== null) seen.add(num);
    const d = resolve(ref, objects);
    if (!isDict(d)) return;
    const kids = resolve(d.get('Kids'), objects);
    if (Array.isArray(kids) && !isName(d.get('Type'), 'Page')) kids.forEach((k) => walk(k, depth + 1));
    else pages.push(d);
  };
  const root = trailer ? resolve(trailer.get('Root'), objects) : null;
  const top = isDict(root) ? root.get('Pages') : null;
  if (top) walk(top, 0);
  if (pages.length) return pages;
  // No usable page tree: fall back to every /Type /Page object in file order.
  return [...objects.entries()].filter(([, e]) => isDict(e.dict) && isName(e.dict.get('Type'), 'Page')).sort((a, b) => a[0] - b[0]).map(([, e]) => e.dict);
}

/**
 * @param {Uint8Array} bytes
 * @param {(bytes: Uint8Array) => Promise<Uint8Array|null>} inflate
 * @returns {Promise<{pages: {lines: object[]}[], flags: object}>}
 */
export async function extractPdfLines(bytes, inflate) {
  const flags = { notPdf: false, encrypted: false, pageCount: 0, pagesWithText: 0, unreadableFonts: false, undecodable: 0 };
  const binaryStr = bytesToBinaryString(bytes);
  if (!binaryStr.startsWith('%PDF') && !binaryStr.slice(0, 1024).includes('%PDF')) { flags.notPdf = true; return { pages: [], flags }; }
  const objects = scanObjects(binaryStr);
  await expandObjectStreams(objects, binaryStr, inflate);
  const trailer = findTrailer(binaryStr, objects);
  if (trailer && trailer.has('Encrypt')) { flags.encrypted = true; return { pages: [], flags }; }
  const plist = pageList(objects, trailer);
  flags.pageCount = plist.length;
  const fontCache = new Map();
  const out = [];
  let pageNo = 0;
  for (const page of plist) {
    pageNo++;
    const res = inherited(page, 'Resources', objects);
    const fonts = new Map();
    const fdict = isDict(res) ? resolve(res.get('Font'), objects) : null;
    if (isDict(fdict)) {
      for (const [name, ref] of fdict.map) {
        const key = ref instanceof PRef ? ref.num : null;
        if (key !== null && fontCache.has(key)) { fonts.set(name, fontCache.get(key)); continue; }
        const f = await loadFont(ref, objects, binaryStr, inflate);
        if (key !== null) fontCache.set(key, f);
        fonts.set(name, f);
      }
    }
    let contents = page.get('Contents');
    const refs = Array.isArray(contents) ? contents : [contents];
    let text = '';
    for (const r of refs) {
      const ref = r instanceof PRef ? r : null;
      const entry = ref ? objects.get(ref.num) : null;
      if (!entry) continue;
      const data = await decodeStream(entry, binaryStr, inflate);
      if (data) text += bytesToBinaryString(data) + '\n';
      else flags.undecodable++;
    }
    const runs = textRuns(text, fonts);
    if (runs.some((r) => r.unreadable)) flags.unreadableFonts = true;
    const lines = groupLines(runs.filter((r) => r.text !== ''), pageNo);
    if (lines.length) flags.pagesWithText++;
    out.push({ lines });
  }
  return { pages: out, flags };
}

